def get_stock_ledger_entries(
	previous_sle,
	operator=None,
	order="desc",
	limit=None,
	for_update=False,
	debug=False,
	check_serial_no=True,
	extra_cond=None,
	for_report=False,
	fields=None,
):
	"""get stock ledger entries filtered by specific posting datetime conditions"""
	conditions = f" and posting_datetime {operator} %(posting_datetime)s"

	if item_code := previous_sle.get("item_code"):
		if isinstance(item_code, list | tuple):
			conditions += " and item_code in %(item_code)s"
		else:
			conditions += " and item_code = %(item_code)s"

	if warehouse := previous_sle.get("warehouse"):
		if isinstance(warehouse, list | tuple):
			conditions += " and warehouse in %(warehouse)s"

		else:
			conditions += " and warehouse = %(warehouse)s"

	if check_serial_no and previous_sle.get("serial_no"):
		# conditions += " and serial_no like {}".format(frappe.db.escape('%{0}%'.format(previous_sle.get("serial_no"))))
		serial_no = previous_sle.get("serial_no")
		conditions += (
			""" and
			(
				serial_no = {}
				or serial_no like {}
				or serial_no like {}
				or serial_no like {}
			)
		"""
		).format(
			frappe.db.escape(serial_no),
			frappe.db.escape(f"{serial_no}\n%"),
			frappe.db.escape(f"%\n{serial_no}"),
			frappe.db.escape(f"%\n{serial_no}\n%"),
		)

	if not previous_sle.get("posting_datetime"):
		# Derive only when the caller has not supplied the stored posting_datetime. Re-deriving it
		# would shift the boundary for rows whose stored value differs from posting_date + posting_time.
		if not previous_sle.get("posting_date"):
			previous_sle["posting_datetime"] = "1900-01-01 00:00:00"
		else:
			posting_time = previous_sle.get("posting_time")
			if not posting_time:
				posting_time = "00:00:00"

			previous_sle["posting_datetime"] = get_combine_datetime(
				previous_sle["posting_date"], posting_time
			)

	if operator in (">", "<=") and previous_sle.get("name"):
		conditions += " and name!=%(name)s"

	if extra_cond:
		conditions += f"{extra_cond}"

	if for_report and previous_sle.get("project"):
		conditions += " and project = %(project)s"

	select_fields = ", ".join(f"`{field}`" for field in fields) if fields else "*"

	# nosemgrep
	return frappe.db.sql(
		"""
		select {select_fields}, posting_datetime as "timestamp"
		from `tabStock Ledger Entry`
		where is_cancelled = 0
		{conditions}
		order by posting_datetime {order}, creation {order}
		{limit} {for_update}""".format(
			select_fields=select_fields,
			conditions=conditions,
			limit=limit or "",
			for_update=for_update and "for update" or "",
			order=order,
		),
		previous_sle,
		as_dict=1,
		debug=debug,
	)

def get_sle_entries_by_names(names):
	"""Fetch and lock complete stock ledger entry rows for the given names."""
	if not names:
		return []

	# nosemgrep
	return frappe.db.sql(
		"""
		select *, posting_datetime as "timestamp"
		from `tabStock Ledger Entry`
		where name in %(names)s and is_cancelled = 0
		for update""",
		{"names": names},
		as_dict=1,
	)

def get_prior_ledger_condition(table, posting_datetime, creation):
	"""Restrict a ledger lookup to the entries that precede a voucher in ledger order."""
	if creation:
		return (table.posting_datetime < posting_datetime) | (
			(table.posting_datetime == posting_datetime) & (table.creation < creation)
		)
	return table.posting_datetime <= posting_datetime

def set_posting_datetime(self):
	from erpnext.stock.utils import get_combine_datetime

	self.posting_datetime = get_combine_datetime(self.posting_date, self.posting_time)

def validate_inventory_dimension_negative_stock(self):
	if self.is_cancelled or self.actual_qty >= 0:
		return

	dimensions = self._get_inventory_dimensions()
	if not dimensions:
		return

	flt_precision = cint(frappe.db.get_default("float_precision")) or 2
	available_qty = self.get_available_qty_after_prev_transaction(dimensions)

	diff = flt(available_qty + flt(self.actual_qty), flt_precision)  # qty after current transaction
	if diff < 0 and abs(diff) > 0.0001:
		self.throw_validation_error(diff, dimensions)

	if not self.flags.defer_future_dimension_check:
		self.validate_future_inventory_dimension_balance(diff, dimensions, flt_precision)

def validate_future_dimension_balance_after_voucher(self):
	if self.is_cancelled or self.actual_qty >= 0:
		return

	dimensions = self._get_inventory_dimensions()
	if not dimensions:
		return

	flt_precision = cint(frappe.db.get_default("float_precision")) or 2
	balance = flt(self.get_available_qty_after_prev_transaction(dimensions), flt_precision)
	self.validate_future_inventory_dimension_balance(balance, dimensions, flt_precision)

def validate_future_inventory_dimension_balance(self, balance, dimensions, precision):
	for actual_qty in self.get_future_dimension_qty(dimensions):
		balance = flt(balance + flt(actual_qty), precision)
		if balance < 0 and abs(balance) > 0.0001:
			self.throw_validation_error(balance, dimensions)

def get_dimension_sle_query(self, sle, dimensions):
	query = frappe.qb.from_(sle).where(
		(sle.item_code == self.item_code)
		& (sle.warehouse == self.warehouse)
		& (sle.company == self.company)
		& (sle.is_cancelled == 0)
	)

	for dimension, values in dimensions.items():
		query = query.where(sle[dimension] == values.get("value"))

	return query

def _get_inventory_dimensions(self):
	inv_dimensions = get_inventory_dimensions()
	inv_dimension_dict = {}
	for dimension in inv_dimensions:
		if not dimension.get("validate_negative_stock") or not self.get(dimension.fieldname):
			continue

		dimension["value"] = self.get(dimension.fieldname)
		inv_dimension_dict.setdefault(dimension.fieldname, dimension)

	return inv_dimension_dict

def validate_serial_no_inventory_dimension(self):
	if self.is_cancelled or self.actual_qty >= 0 or not self.has_serial_no:
		return

	dimensions = get_inventory_dimensions()
	if not dimensions:
		return

	serial_nos = get_serial_nos(self.serial_and_batch_bundle)
	if not serial_nos and self.serial_no:
		serial_nos = get_parsed_serial_nos(self.serial_no)

	if not serial_nos:
		return

	for serial_no, values in self.get_last_inward_dimensions(serial_nos, dimensions).items():
		mismatches = []
		for dimension in dimensions:
			fieldname = dimension.fieldname
			expected_value = values.get(fieldname)
			if expected_value != self.get(fieldname):
				mismatches.append(
					_('{0}: expected "{1}", got "{2}"').format(
						dimension.dimension_name,
						expected_value or _("Not Set"),
						self.get(fieldname),
					)
				)

		if mismatches:
			frappe.throw(
				_("Serial No {0} is not available in the selected inventory dimensions: {1}").format(
					frappe.bold(serial_no), frappe.bold(", ".join(mismatches))
				),
				title=_("Incorrect Inventory Dimension"),
				exc=SerialNoInventoryDimensionError,
			)

def on_submit(self):
	self.check_stock_frozen_date()

	# Added to handle few test cases where serial_and_batch_bundles are not required
	if frappe.in_test and frappe.flags.ignore_serial_batch_bundle_validation:
		return

	# a write-off moves no serial no or batch; the reset of an Adjustment Entry does
	if self.is_adjustment_entry and not self.serial_and_batch_bundle:
		return

	if not self.get("via_landed_cost_voucher"):
		SerialBatchBundle(
			sle=self,
			item_code=self.item_code,
			warehouse=self.warehouse,
			company=self.company,
		)

	self.validate_serial_batch_no_bundle()

def validate_mandatory(self):
	mandatory = ["warehouse", "posting_date", "voucher_type", "voucher_no", "company"]
	for k in mandatory:
		if not self.get(k):
			frappe.throw(_("{0} is required").format(_(self.meta.get_label(k))))

	if self.voucher_type != "Stock Reconciliation" and not self.actual_qty:
		frappe.throw(_("Actual Qty is mandatory"))

def validate_serial_batch_no_bundle(self):
	if self.is_cancelled == 1:
		return

	item_detail = frappe.get_cached_value(
		"Item",
		self.item_code,
		["has_serial_no", "has_batch_no", "is_stock_item", "has_variants", "stock_uom"],
		as_dict=1,
	)

	values_to_be_change = {}
	if self.has_batch_no != item_detail.has_batch_no:
		values_to_be_change["has_batch_no"] = item_detail.has_batch_no

	if self.has_serial_no != item_detail.has_serial_no:
		values_to_be_change["has_serial_no"] = item_detail.has_serial_no

	if values_to_be_change:
		self.db_set(values_to_be_change)

	if not item_detail:
		self.throw_error_message(f"Item {self.item_code} not found")

	if item_detail.has_variants:
		self.throw_error_message(
			f"Stock cannot exist for Item {self.item_code} since has variants",
			ItemTemplateCannotHaveStock,
		)

	if item_detail.is_stock_item != 1:
		self.throw_error_message(f"Item {self.item_code} must be a stock Item")

	if item_detail.has_serial_no or item_detail.has_batch_no:
		if not self.serial_and_batch_bundle:
			self.throw_error_message(f"Serial No / Batch No are mandatory for Item {self.item_code}")

	if self.serial_and_batch_bundle and not item_detail.has_serial_no and not item_detail.has_batch_no:
		self.throw_error_message(f"Serial No and Batch No are not allowed for Item {self.item_code}")

def scrub_posting_time(self):
	if not self.posting_time or self.posting_time == "00:0":
		self.posting_time = "00:00"

def validate_batch(self):
	if self.batch_no and self.voucher_type != "Stock Entry":
		if (self.voucher_type in ["Purchase Receipt", "Purchase Invoice"] and self.actual_qty < 0) or (
			self.voucher_type in ["Delivery Note", "Sales Invoice"] and self.actual_qty > 0
		):
			return

		expiry_date = frappe.db.get_value("Batch", self.batch_no, "expiry_date")
		if expiry_date:
			if getdate(self.posting_date) > getdate(expiry_date):
				frappe.throw(
					_("Batch {0} of Item {1} has expired.").format(self.batch_no, self.item_code)
				)

def validate_and_set_fiscal_year(self):
	if not self.fiscal_year:
		self.fiscal_year = get_fiscal_year(self.posting_date, company=self.company)[0]
	else:
		from erpnext.accounts.utils import validate_fiscal_year

		validate_fiscal_year(
			self.posting_date, self.fiscal_year, self.company, self.meta.get_label("posting_date"), self
		)

def block_transactions_against_group_warehouse(self):
	from erpnext.stock.utils import is_group_warehouse

	is_group_warehouse(self.warehouse)

def validate_with_last_transaction_posting_time(self):
	authorized_role = frappe.get_single_value(
		"Stock Settings", "role_allowed_to_create_edit_back_dated_transactions"
	)
	if authorized_role:
		authorized_users = get_users(authorized_role)
		if authorized_users and frappe.session.user not in authorized_users:
			last_transaction_time = frappe.db.sql(
				"""
				select MAX(timestamp(posting_date, posting_time)) as posting_time
				from `tabStock Ledger Entry`
				where docstatus = 1 and is_cancelled = 0 and item_code = %s
				and warehouse = %s""",
				(self.item_code, self.warehouse),
			)[0][0]

			cur_doc_posting_datetime = "{} {}".format(
				self.posting_date,
				self.get("posting_time") or "00:00:00",
			)

			if last_transaction_time and get_datetime(cur_doc_posting_datetime) < get_datetime(
				last_transaction_time
			):
				msg = _("Last Stock Transaction for item {0} under warehouse {1} was on {2}.").format(
					frappe.bold(self.item_code),
					frappe.bold(self.warehouse),
					frappe.bold(last_transaction_time),
				)

				msg += "<br><br>" + _(
					"You are not authorized to make/edit Stock Transactions for Item {0} under warehouse {1} before this time."
				).format(frappe.bold(self.item_code), frappe.bold(self.warehouse))

				msg += "<br><br>" + _("Please contact any of the following users for this transaction.")
				msg += "<br>" + "<br>".join(authorized_users)
				frappe.throw(msg, BackDatedStockTransaction, title=_("Backdated Stock Entry"))

def get_or_make_bin(item_code: str, warehouse: str) -> str:
	bin_record = frappe.db.get_value("Bin", {"item_code": item_code, "warehouse": warehouse})

	if not bin_record:
		bin_obj = _create_bin(item_code, warehouse)
		bin_record = bin_obj.name
	return bin_record

def get_combine_datetime(posting_date, posting_time):
	import datetime

	if isinstance(posting_date, str):
		posting_date = getdate(posting_date)

	if isinstance(posting_time, str):
		posting_time = get_time(posting_time)

	if isinstance(posting_time, datetime.timedelta):
		posting_time = (datetime.datetime.min + posting_time).time()

	return datetime.datetime.combine(posting_date, posting_time)

def validate_warehouse_company(warehouse, company):
	warehouse_company = frappe.db.get_value("Warehouse", warehouse, "company", cache=True)
	if warehouse_company and warehouse_company != company:
		frappe.throw(
			_("Warehouse {0} does not belong to company {1}").format(warehouse, company),
			InvalidWarehouseCompany,
		)

def validate_disabled_warehouse(warehouse):
	if frappe.db.get_value("Warehouse", warehouse, "disabled", cache=True):
		frappe.throw(
			_("Disabled Warehouse {0} cannot be used for this transaction.").format(
				get_link_to_form("Warehouse", warehouse)
			)
		)

@frappe.whitelist()
def submit(self):
	"""Submit the document. Sets `docstatus` = 1, then saves."""
	return self._submit()

def _submit(self):
	"""Submit the document. Sets `docstatus` = 1, then saves."""
	self.docstatus = DocStatus.SUBMITTED
	return self.save()

def save(self, *args, **kwargs) -> "Self":
	"""Wrapper for _save"""
	return self._save(*args, **kwargs)

def db_insert(self, ignore_if_duplicate=False):
	"""INSERT the document (with valid columns) in the database.

	args:
	        ignore_if_duplicate: ignore primary key collision
	                                        at database level (postgres)
	                                        in python (mariadb)
	"""
	if not self.name:
		# name will be set by document class in most cases
		set_new_name(self)

	conflict_handler = ""
	returning = ""
	# On postgres we can't implcitly ignore PK collision
	# So instruct pg to ignore `name` field conflicts
	if (
		(ignore_if_duplicate or self.meta.autoname == "hash")
		and frappe.db.db_type == "postgres"
		and (self.flags.retry_count or 0) < 5
	):
		conflict_handler = "on conflict (name) do nothing"
		if self.meta.autoname == "hash":
			returning = "RETURNING name"

	if not self.creation:
		self.creation = self.modified = now()
		self.owner = self.modified_by = frappe.session.user

	# if doctype is "DocType", don't insert null values as we don't know who is valid yet
	d = self.get_valid_dict(
		convert_dates_to_str=True,
		ignore_nulls=self.doctype in DOCTYPES_FOR_DOCTYPE,
		ignore_virtual=True,
	)

	columns = list(d)
	try:
		name = frappe.db.sql(
			"""INSERT INTO `tab{doctype}` ({columns})
				VALUES ({values}) {conflict_handler} {returning}""".format(
				doctype=self.doctype,
				columns=", ".join("`" + c + "`" for c in columns),
				values=", ".join(["%s"] * len(columns)),
				conflict_handler=conflict_handler,
				returning=returning,
			),
			list(d.values()),
		)
		if (
			frappe.db.db_type == "postgres" and self.meta.autoname == "hash" and not name
		):  # To avoid a transaction block, we regen in try (pg specific)
			return self._handle_hash_conflict()
	except Exception as e:
		if frappe.db.is_primary_key_violation(e):
			if self.meta.autoname == "hash":
				# hash collision? try again
				return self._handle_hash_conflict()

			if not ignore_if_duplicate:
				frappe.msgprint(
					_("{0} {1} already exists").format(_(self.doctype), frappe.bold(self.name)),
					title=_("Duplicate Name"),
					indicator="red",
				)
				raise frappe.DuplicateEntryError(self.doctype, self.name, e)

		elif frappe.db.is_unique_key_violation(e):
			# unique constraint
			self.show_unique_validation_message(e)

		else:
			raise

	self.set("__islocal", False)

def db_update(self):
	if self.get("__islocal") or not self.name:
		self.db_insert()
		return

	d = self.get_valid_dict(
		convert_dates_to_str=True,
		ignore_nulls=self.doctype in DOCTYPES_FOR_DOCTYPE,
		ignore_virtual=True,
	)

	# don't update name, as case might've been changed
	name = cstr(d["name"])
	del d["name"]

	columns = list(d)

	try:
		frappe.db.sql(
			"""UPDATE `tab{doctype}`
			SET {values} WHERE `name`=%s""".format(
				doctype=self.doctype, values=", ".join("`" + c + "`=%s" for c in columns)
			),
			[*list(d.values()), name],
		)

	except Exception as e:
		if frappe.db.is_data_too_long(e):
			column = re.search(r"column\s+'([^']+)'", e.args[1])
			if column:
				label = self.get_label_from_fieldname(column.group(1))

				# data too long for column
				frappe.throw(
					_(
						"The value of the field {0} is too long in the {1} document. To resolve this issue, please reduce the value length or change the {0} field Type to Long Text using customize form, and then try again."
					).format(frappe.bold(label), frappe.bold(self.doctype)),
					title=_("Value Too Long"),
				)

		if frappe.db.is_unique_key_violation(e):
			self.show_unique_validation_message(e)
		else:
			raise

def run_post_save_methods(self):
	"""Run standard methods after `INSERT` or `UPDATE`. Standard Methods are:

	- `on_update` for **Save**.
	- `on_update`, `on_submit` for **Submit**.
	- `on_cancel` for **Cancel**
	- `update_after_submit` for **Update after Submit**"""

	if self._action == "save":
		self.run_method("on_update")
	elif self._action == "submit":
		self.run_method("on_update")
		self.run_method("on_submit")
	elif self._action == "cancel":
		self.run_method("on_cancel")
		self.check_no_back_links_exist()
	elif self._action == "update_after_submit":
		self.run_method("on_update_after_submit")

	if not (frappe.flags.in_import and self.is_new()):
		self.clear_cache()

	if self.flags.get("notify_update", True):
		self.notify_update()

	from frappe.utils.global_search import update_global_search

	update_global_search(self)

	self.save_version()

	self.run_method("on_change")

	if (self.doctype, self.name) in frappe.flags.currently_saving:
		frappe.flags.currently_saving.remove((self.doctype, self.name))

def run_method(self, method: str, *args, **kwargs):
	"""run standard triggers, plus those in hooks"""

	if method.startswith("_"):
		raise Exception("Run method is for hooks, avoid usage on internal methods")

	def fn(self, *args, **kwargs):
		method_object = getattr(self, method, None)

		# Cannot have a field with same name as method
		# If method found in __dict__, expect it to be callable
		if method in self.__dict__ or callable(method_object):
			return method_object(*args, **kwargs)

	fn.__name__ = str(method)
	out = Document.hook(fn)(self, *args, **kwargs)

	self.run_notifications(method)
	run_webhooks(self, method)
	run_server_script_for_doc_event(self, method)
	run_automations(self, method)

	return out

@after_response_wrapper
@Request.application
def application(request: Request):
	response = None

	try:
		init_request(request)

		validate_auth()

		if request.method == "OPTIONS":
			response = Response()

		elif frappe.form_dict.cmd:
			from frappe.deprecation_dumpster import deprecation_warning

			deprecation_warning(
				"unknown",
				"v17",
				f"{frappe.form_dict.cmd}: Sending `cmd` for RPC calls is deprecated, call REST API instead `/api/method/cmd`",
			)
			frappe.handler.handle()
			response = frappe.utils.response.build_response("json")

		elif request.path.startswith("/api/"):
			response = frappe.api.handle(request)

		elif request.path.startswith("/backups"):
			response = frappe.utils.response.download_backup(request.path)

		elif request.path.startswith("/private/files/"):
			response = frappe.utils.response.download_private_file(request.path)

		elif request.path == "/.well-known/security.txt" and request.method == "GET":
			if request.scheme != "https":
				raise NotFound
			security_settings = frappe.get_doc("Security Settings")
			response = Response(security_settings.security_txt, content_type="text/plain")

		elif request.path.startswith("/.well-known/") and request.method == "GET":
			response = handle_wellknown(request.path)

		elif request.method in ("GET", "HEAD", "POST"):
			response = get_response()

		else:
			raise NotFound

	except Exception as e:
		response = e.get_response(request.environ) if isinstance(e, HTTPException) else handle_exception(e)
		if db := getattr(frappe.local, "db", None):
			db.rollback(chain=True)

	else:
		sync_database()

	finally:
		# Important note:
		# this function *must* always return a response, hence any exception thrown outside of
		# try..catch block like this finally block needs to be handled appropriately.

		try:
			run_after_request_hooks(request, response)
		except Exception:
			# We can not handle exceptions safely here.
			frappe.logger().error("Failed to run after request hook", exc_info=True)

	log_request(request, response)
	process_response(response)

	return response

def sync_database():
	db = getattr(frappe.local, "db", None)
	if not db:
		# db isn't initialized, can't commit or rollback
		return

	# if HTTP method would change server state, commit if necessary
	if frappe.local.request.method in UNSAFE_HTTP_METHODS or frappe.local.flags.commit:
		db.commit(chain=True)
	else:
		db.rollback(chain=True)

	# update session
	if session := getattr(frappe.local, "session_obj", None):
		frappe.request.after_response.add(session.update)

@handle_does_not_exist_error
def handle_exception(e):
	response = None
	http_status_code = getattr(e, "http_status_code", 500)
	accept_header = frappe.get_request_header("Accept") or ""
	respond_as_json = (
		frappe.get_request_header("Accept") and (frappe.local.is_ajax or "application/json" in accept_header)
	) or (frappe.local.request.path.startswith("/api/") and not accept_header.startswith("text"))

	if not frappe.session.user:
		# If session creation fails then user won't be unset. This causes a lot of code that
		# assumes presence of this to fail. Session creation fails => guest or expired login
		# usually.
		frappe.session.user = "Guest"

	if getattr(frappe.local, "mcp_request", None):
		from frappe.mcp.transport import error_response

		response = error_response(e)

	elif respond_as_json:
		# handle ajax responses first
		# if the request is ajax, send back the trace or error message
		response = frappe.utils.response.report_error(http_status_code)

	elif isinstance(e, frappe.SessionStopped):
		response = frappe.utils.response.handle_session_stopped()

	elif (
		http_status_code == 500
		and (frappe.db and isinstance(e, frappe.db.InternalError))
		and (frappe.db and (frappe.db.is_deadlocked(e) or frappe.db.is_timedout(e)))
	):
		http_status_code = 508

	elif http_status_code == 401:
		response = ErrorPage(
			http_status_code=http_status_code,
			title=_("Session Expired"),
			message=_("Your session has expired, please login again to continue."),
		).render()

	elif http_status_code == 403:
		response = ErrorPage(
			http_status_code=http_status_code,
			title=_("Not Permitted"),
			message=_("You do not have enough permissions to complete the action"),
		).render()

	elif http_status_code == 404:
		response = ErrorPage(
			http_status_code=http_status_code,
			title=_("Not Found"),
			message=_("The resource you are looking for is not available"),
		).render()

	elif http_status_code == 429:
		response = frappe.rate_limiter.respond()

	else:
		response = ErrorPage(
			http_status_code=http_status_code, title=_("Server Error"), message=_("Uncaught Exception")
		).render()

	if e.__class__ == frappe.AuthenticationError:
		if hasattr(frappe.local, "login_manager"):
			frappe.local.login_manager.clear_cookies()

	if http_status_code >= 500 or frappe.conf.developer_mode:
		log_error_snapshot(e)

	if frappe.conf.get("developer_mode") and not respond_as_json:
		# don't fail silently for non-json response errors
		print(frappe.get_traceback())

	return response
